using AutoMapper;
using MediatR;
using WhatsBiz.Application.Common.Exceptions;
using WhatsBiz.Application.Common.Interfaces;
using WhatsBiz.Application.Features.Products.DTOs;
using WhatsBiz.Domain.Products;

namespace WhatsBiz.Application.Features.Products.MasterData;

public sealed class GetProductCategoriesQueryHandler(IProductRepository repository) : IRequestHandler<GetProductCategoriesQuery, IReadOnlyCollection<ProductCategoryDto>>
{
    public async Task<IReadOnlyCollection<ProductCategoryDto>> Handle(GetProductCategoriesQuery request, CancellationToken cancellationToken) { var items = await repository.GetCategoriesAsync(cancellationToken); var filtered = items.Where(x => (!request.IsActive.HasValue || x.IsActive == request.IsActive) && (string.IsNullOrWhiteSpace(request.Search) || x.CategoryCode.Contains(request.Search, StringComparison.OrdinalIgnoreCase) || x.CategoryName.Contains(request.Search, StringComparison.OrdinalIgnoreCase))).ToArray(); return BuildTree(filtered, null); }
    private static ProductCategoryDto[] BuildTree(IReadOnlyCollection<ProductCategory> categories, Guid? parentId) => categories.Where(x => x.ParentCategoryId == parentId).OrderBy(x => x.DisplayOrder).ThenBy(x => x.CategoryName).Select(x => new ProductCategoryDto(x.ProductCategoryId, x.CategoryCode, x.CategoryName, x.Description, x.DisplayOrder, x.ParentCategoryId, x.IsActive, BuildTree(categories, x.ProductCategoryId))).ToArray();
}
public sealed class CreateProductCategoryCommandHandler(IProductRepository repository, ICurrentUserService currentUser) : IRequestHandler<CreateProductCategoryCommand, ProductCategoryDto>
{
    public async Task<ProductCategoryDto> Handle(CreateProductCategoryCommand request, CancellationToken cancellationToken)
    {
        var item = new ProductCategory();
        var code = MasterDataCode.Resolve(request.Input.CategoryCode, "CAT", item.ProductCategoryId);
        if (await repository.CategoryCodeExistsAsync(code, null, cancellationToken)) throw new BusinessRuleException("Category code already exists.");
        if (request.Input.ParentCategoryId.HasValue && await repository.GetCategoryAsync(request.Input.ParentCategoryId.Value, false, cancellationToken) is null) throw new BusinessRuleException("Parent category was not found.");
        item.CategoryCode = code; item.CategoryName = request.Input.CategoryName.Trim(); item.Description = request.Input.Description?.Trim(); item.DisplayOrder = request.Input.DisplayOrder; item.ParentCategoryId = request.Input.ParentCategoryId; item.IsActive = request.Input.IsActive; item.CreatedBy = currentUser.Username;
        repository.Add(item); await repository.SaveChangesAsync(cancellationToken); return Map(item);
    }
    internal static ProductCategoryDto Map(ProductCategory x) => new(x.ProductCategoryId, x.CategoryCode, x.CategoryName, x.Description, x.DisplayOrder, x.ParentCategoryId, x.IsActive, []);
}
public sealed class UpdateProductCategoryCommandHandler(IProductRepository repository, ICurrentUserService currentUser) : IRequestHandler<UpdateProductCategoryCommand, ProductCategoryDto> { public async Task<ProductCategoryDto> Handle(UpdateProductCategoryCommand request, CancellationToken cancellationToken) { var item = await repository.GetCategoryAsync(request.Id, true, cancellationToken) ?? throw new EntityNotFoundException("Category was not found."); var code = MasterDataCode.PreserveOrUse(request.Input.CategoryCode, item.CategoryCode); if (await repository.CategoryCodeExistsAsync(code, request.Id, cancellationToken)) throw new BusinessRuleException("Category code already exists."); if (request.Input.ParentCategoryId.HasValue && await repository.GetCategoryAsync(request.Input.ParentCategoryId.Value, false, cancellationToken) is null) throw new BusinessRuleException("Parent category was not found."); item.CategoryCode = code; item.CategoryName = request.Input.CategoryName.Trim(); item.Description = request.Input.Description?.Trim(); item.DisplayOrder = request.Input.DisplayOrder; item.ParentCategoryId = request.Input.ParentCategoryId; item.IsActive = request.Input.IsActive; item.ModifiedOn = DateTimeOffset.UtcNow; item.ModifiedBy = currentUser.Username; await repository.SaveChangesAsync(cancellationToken); return CreateProductCategoryCommandHandler.Map(item); } }
public sealed class DeleteProductCategoryCommandHandler(IProductRepository repository, ICurrentUserService currentUser) : IRequestHandler<DeleteProductCategoryCommand> { public async Task Handle(DeleteProductCategoryCommand request, CancellationToken cancellationToken) { var item = await repository.GetCategoryAsync(request.Id, true, cancellationToken) ?? throw new EntityNotFoundException("Category was not found."); if (await repository.CategoryHasChildrenOrProductsAsync(request.Id, cancellationToken)) throw new BusinessRuleException("Category cannot be deleted while it has child categories or products."); SoftDelete(item, currentUser.Username); await repository.SaveChangesAsync(cancellationToken); } private static void SoftDelete(ProductMasterEntity item, string? user) { item.IsDeleted = true; item.IsActive = false; item.ModifiedOn = DateTimeOffset.UtcNow; item.ModifiedBy = user; } }

public sealed class GetBrandsQueryHandler(IProductRepository repository, IMapper mapper) : IRequestHandler<GetBrandsQuery, IReadOnlyCollection<BrandDto>> { public async Task<IReadOnlyCollection<BrandDto>> Handle(GetBrandsQuery request, CancellationToken cancellationToken) { var items = await repository.GetBrandsAsync(cancellationToken); return mapper.Map<IReadOnlyCollection<BrandDto>>(items.Where(x => (!request.IsActive.HasValue || x.IsActive == request.IsActive) && (string.IsNullOrWhiteSpace(request.Search) || x.BrandCode.Contains(request.Search, StringComparison.OrdinalIgnoreCase) || x.BrandName.Contains(request.Search, StringComparison.OrdinalIgnoreCase)))); } }
public sealed class CreateBrandCommandHandler(IProductRepository repository, ICurrentUserService currentUser, IMapper mapper) : IRequestHandler<CreateBrandCommand, BrandDto> { public async Task<BrandDto> Handle(CreateBrandCommand request, CancellationToken cancellationToken) { var item = new Brand(); var code = MasterDataCode.Resolve(request.Input.BrandCode, "BR", item.BrandId); if (await repository.BrandCodeExistsAsync(code, null, cancellationToken)) throw new BusinessRuleException("Brand code already exists."); item.BrandCode = code; item.BrandName = request.Input.BrandName.Trim(); item.Description = request.Input.Description?.Trim(); item.Logo = request.Input.Logo?.Trim(); item.IsActive = request.Input.IsActive; item.CreatedBy = currentUser.Username; repository.Add(item); await repository.SaveChangesAsync(cancellationToken); return mapper.Map<BrandDto>(item); } }
public sealed class UpdateBrandCommandHandler(IProductRepository repository, ICurrentUserService currentUser, IMapper mapper) : IRequestHandler<UpdateBrandCommand, BrandDto> { public async Task<BrandDto> Handle(UpdateBrandCommand request, CancellationToken cancellationToken) { var item = await repository.GetBrandAsync(request.Id, true, cancellationToken) ?? throw new EntityNotFoundException("Brand was not found."); var code = MasterDataCode.PreserveOrUse(request.Input.BrandCode, item.BrandCode); if (await repository.BrandCodeExistsAsync(code, request.Id, cancellationToken)) throw new BusinessRuleException("Brand code already exists."); item.BrandCode = code; item.BrandName = request.Input.BrandName.Trim(); item.Description = request.Input.Description?.Trim(); item.Logo = request.Input.Logo?.Trim(); item.IsActive = request.Input.IsActive; item.ModifiedOn = DateTimeOffset.UtcNow; item.ModifiedBy = currentUser.Username; await repository.SaveChangesAsync(cancellationToken); return mapper.Map<BrandDto>(item); } }
public sealed class DeleteBrandCommandHandler(IProductRepository repository, ICurrentUserService currentUser) : IRequestHandler<DeleteBrandCommand> { public async Task Handle(DeleteBrandCommand request, CancellationToken cancellationToken) { var item = await repository.GetBrandAsync(request.Id, true, cancellationToken) ?? throw new EntityNotFoundException("Brand was not found."); if (await repository.BrandHasProductsAsync(request.Id, cancellationToken)) throw new BusinessRuleException("Brand cannot be deleted while it is used by products."); item.IsDeleted = true; item.IsActive = false; item.ModifiedOn = DateTimeOffset.UtcNow; item.ModifiedBy = currentUser.Username; await repository.SaveChangesAsync(cancellationToken); } }

