public sealed class CreateUnitOfMeasureCommandHandler(IProductRepository repository, ICurrentUserService currentUser, IMapper mapper) : IRequestHandler<CreateUnitOfMeasureCommand, UnitOfMeasureDto> { public async Task<UnitOfMeasureDto> Handle(CreateUnitOfMeasureCommand request, CancellationToken cancellationToken) { var item = new UnitOfMeasure(); var code = MasterDataCode.Resolve(request.Input.UnitCode, "UOM", item.UnitId); if (await repository.UnitCodeExistsAsync(code, null, cancellationToken)) throw new BusinessRuleException("Unit code already exists."); item.UnitCode = code; item.UnitName = request.Input.UnitName.Trim(); item.ShortName = request.Input.ShortName.Trim(); item.DecimalPlaces = request.Input.DecimalPlaces; item.IsActive = request.Input.IsActive; item.CreatedBy = currentUser.Username; repository.Add(item); await repository.SaveChangesAsync(cancellationToken); return mapper.Map<UnitOfMeasureDto>(item); } }
public sealed class UpdateUnitOfMeasureCommandHandler(IProductRepository repository, ICurrentUserService currentUser, IMapper mapper) : IRequestHandler<UpdateUnitOfMeasureCommand, UnitOfMeasureDto> { public async Task<UnitOfMeasureDto> Handle(UpdateUnitOfMeasureCommand request, CancellationToken cancellationToken) { var item = await repository.GetUnitAsync(request.Id, true, cancellationToken) ?? throw new EntityNotFoundException("Unit was not found."); var code = MasterDataCode.PreserveOrUse(request.Input.UnitCode, item.UnitCode); if (await repository.UnitCodeExistsAsync(code, request.Id, cancellationToken)) throw new BusinessRuleException("Unit code already exists."); item.UnitCode = code; item.UnitName = request.Input.UnitName.Trim(); item.ShortName = request.Input.ShortName.Trim(); item.DecimalPlaces = request.Input.DecimalPlaces; item.IsActive = request.Input.IsActive; item.ModifiedOn = DateTimeOffset.UtcNow; item.ModifiedBy = currentUser.Username; await repository.SaveChangesAsync(cancellationToken); return mapper.Map<UnitOfMeasureDto>(item); } }
public sealed class DeleteUnitOfMeasureCommandHandler(IProductRepository repository, ICurrentUserService currentUser) : IRequestHandler<DeleteUnitOfMeasureCommand> { public async Task Handle(DeleteUnitOfMeasureCommand request, CancellationToken cancellationToken) { var item = await repository.GetUnitAsync(request.Id, true, cancellationToken) ?? throw new EntityNotFoundException("Unit was not found."); if (await repository.UnitHasProductsAsync(request.Id, cancellationToken)) throw new BusinessRuleException("Unit cannot be deleted while it is used by products."); item.IsDeleted = true; item.IsActive = false; item.ModifiedOn = DateTimeOffset.UtcNow; item.ModifiedBy = currentUser.Username; await repository.SaveChangesAsync(cancellationToken); } }

internal static class MasterDataCode
{
    internal static string Resolve(string? requested, string prefix, Guid id) =>
        string.IsNullOrWhiteSpace(requested) ? $"{prefix}-{id:N}" : requested.Trim();

    internal static string PreserveOrUse(string? requested, string existing) =>
        string.IsNullOrWhiteSpace(requested) ? existing : requested.Trim();
}
